#!/usr/bin/env bats
#
# test_scripts.bats - BATS test suite for defensive Bash scripts
# Tests for common_utils.sh and safe_backup.sh

setup() {
    # Create temporary directory for tests
    TEST_TEMP_DIR="$(mktemp -d)"
    export TEST_TEMP_DIR

    # Source common utilities
    SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
    # shellcheck source=test/common_utils.sh
    source "${SCRIPT_DIR}/common_utils.sh"
}

teardown() {
    # Clean up temporary directory
    if [[ -n "$TEST_TEMP_DIR" ]] && [[ -d "$TEST_TEMP_DIR" ]]; then
        rm -rf "$TEST_TEMP_DIR"
    fi
}

# Tests for common_utils.sh

@test "log_info outputs to stderr" {
    run log_info "test message"
    [[ "$status" -eq 0 ]]
}

@test "log_warn outputs to stderr" {
    run log_warn "test warning"
    [[ "$status" -eq 0 ]]
}

@test "log_error outputs to stderr" {
    run log_error "test error"
    [[ "$status" -eq 0 ]]
}

@test "die exits with specified code" {
    run die "test error" 42
    [[ "$status" -eq 42 ]]
}

@test "die defaults to exit code 1" {
    run die "test error"
    [[ "$status" -eq 1 ]]
}

@test "require_command succeeds for existing command" {
    run require_command "bash"
    [[ "$status" -eq 0 ]]
}

@test "require_command fails for non-existent command" {
    run require_command "nonexistent_command_12345"
    [[ "$status" -eq 127 ]]
}

@test "validate_directory succeeds for valid directory" {
    mkdir -p "$TEST_TEMP_DIR/testdir"
    run validate_directory "$TEST_TEMP_DIR/testdir"
    [[ "$status" -eq 0 ]]
}

@test "validate_directory fails for non-existent directory" {
    run validate_directory "$TEST_TEMP_DIR/nonexistent"
    [[ "$status" -eq 2 ]]
}

@test "validate_directory fails for empty path" {
    run validate_directory ""
    [[ "$status" -eq 2 ]]
}

@test "validate_file succeeds for valid file" {
    touch "$TEST_TEMP_DIR/testfile"
    run validate_file "$TEST_TEMP_DIR/testfile"
    [[ "$status" -eq 0 ]]
}

@test "validate_file fails for non-existent file" {
    run validate_file "$TEST_TEMP_DIR/nonexistent"
    [[ "$status" -eq 2 ]]
}

@test "validate_file fails for directory" {
    mkdir -p "$TEST_TEMP_DIR/testdir"
    run validate_file "$TEST_TEMP_DIR/testdir"
    [[ "$status" -eq 2 ]]
}

@test "safe_mkdir creates new directory" {
    run safe_mkdir "$TEST_TEMP_DIR/newdir"
    [[ "$status" -eq 0 ]]
    [[ -d "$TEST_TEMP_DIR/newdir" ]]
}

@test "safe_mkdir succeeds if directory already exists" {
    mkdir -p "$TEST_TEMP_DIR/existingdir"
    run safe_mkdir "$TEST_TEMP_DIR/existingdir"
    [[ "$status" -eq 0 ]]
}

@test "safe_mkdir fails for empty path" {
    run safe_mkdir ""
    [[ "$status" -eq 2 ]]
}

# Tests for safe_backup.sh

@test "safe_backup.sh shows usage with --help" {
    run bash test/safe_backup.sh --help
    [[ "$status" -eq 0 ]]
    [[ "$output" =~ "Usage:" ]]
}

@test "safe_backup.sh fails without arguments" {
    run bash test/safe_backup.sh
    [[ "$status" -eq 2 ]]
}

@test "safe_backup.sh fails with only one argument" {
    run bash test/safe_backup.sh /tmp
    [[ "$status" -eq 2 ]]
}

@test "safe_backup.sh creates backup of directory" {
    # Create source directory with test file
    mkdir -p "$TEST_TEMP_DIR/source"
    echo "test content" > "$TEST_TEMP_DIR/source/testfile.txt"

    # Create backup directory
    mkdir -p "$TEST_TEMP_DIR/backups"

    # Run backup
    run bash test/safe_backup.sh "$TEST_TEMP_DIR/source" "$TEST_TEMP_DIR/backups"
    [[ "$status" -eq 0 ]]

    # Check backup was created
    backup_count=$(find "$TEST_TEMP_DIR/backups" -maxdepth 1 -type d -name "source-backup-*" | wc -l)
    [[ "$backup_count" -eq 1 ]]
}

@test "safe_backup.sh creates compressed backup with --compress" {
    # Create source directory
    mkdir -p "$TEST_TEMP_DIR/source"
    echo "test content" > "$TEST_TEMP_DIR/source/testfile.txt"

    # Create backup directory
    mkdir -p "$TEST_TEMP_DIR/backups"

    # Run compressed backup
    run bash test/safe_backup.sh --compress "$TEST_TEMP_DIR/source" "$TEST_TEMP_DIR/backups"
    [[ "$status" -eq 0 ]]

    # Check compressed backup was created
    backup_count=$(find "$TEST_TEMP_DIR/backups" -maxdepth 1 -type f -name "source-backup-*.tar.gz" | wc -l)
    [[ "$backup_count" -eq 1 ]]
}

@test "safe_backup.sh fails for non-existent source directory" {
    mkdir -p "$TEST_TEMP_DIR/backups"
    run bash test/safe_backup.sh "$TEST_TEMP_DIR/nonexistent" "$TEST_TEMP_DIR/backups"
    [[ "$status" -eq 2 ]]
}

@test "safe_backup.sh verbose mode produces output" {
    mkdir -p "$TEST_TEMP_DIR/source"
    mkdir -p "$TEST_TEMP_DIR/backups"

    run bash test/safe_backup.sh --verbose "$TEST_TEMP_DIR/source" "$TEST_TEMP_DIR/backups"
    [[ "$status" -eq 0 ]]
    [[ "$output" =~ "Source:" ]]
    [[ "$output" =~ "Backup:" ]]
}

